#!/usr/bin/env python3
"""Deterministic ArchML compiler profiles. No downloaded/generated ISA claims.

The reviewed tables below are the source for library/archml/*.aml. --check
verifies checked-in assets. Concrete forms have encodings and P-code; other
extensions are explicitly marked metadata-only. Encoding examples are tested
against independent assembler fixtures in tests/test_archml.c.
"""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def q(s):
    return json.dumps(str(s), ensure_ascii=False)


def ref(kind, name):
    return f'(ref {kind} {name})'


def refs(kind, names):
    return ' '.join(ref(kind, n) for n in names)


def prop(key, value):
    return f'({key} {value})'


class Profile:
    def __init__(self, name):
        self.name = name
        self.records = []
        self.instructions = []

    def add(self, kind, name, *properties):
        self.records.append(f'  ({kind} {name}\n    ' + '\n    '.join(properties) + ')')

    def feature(self, name, description, requires=()):
        self.add('feature', name, prop('doc', q(description)), prop('requires', refs('feature', requires)))

    def reg(self, name, bits, storage, encoding, dwarf=None, offset=0, write='replace'):
        ps = [prop('bits', bits), prop('storage', storage), prop('offset', offset),
              prop('encoding', encoding), prop('write', write)]
        if dwarf is not None:
            ps.append(prop('dwarf', dwarf))
        self.add('register', name, *ps)

    def storage(self, name, bits, scalable=False):
        self.add('storage', name, prop('bits', bits), prop('scalable', str(scalable).lower()))

    def regclass(self, name, registers, bits, reserve=(), **extra):
        self.add('regclass', name, prop('bits', bits), prop('members', refs('register', registers)),
                 prop('reserved', refs('register', reserve)),
                 prop('spill-align', min(max(1, bits // 8), 64)),
                 *(prop(k.replace('_', '-'), v) for k, v in extra.items()))

    def instruction(self, name, base, operands, fields, code, asm, features=('base',),
                    effects='pure', schedule='alu', constraints='none', doc='', **extra):
        if isinstance(base, int):
            base = base.to_bytes(4, 'little').hex()
        self.instructions.append(name)
        mode = {'amd64': 'long64', 'arm64': 'el0', 'risv': 'user'}[self.name]
        uses, defs = [], []
        if self.name == 'amd64':
            if 'x86-condition' in code: uses.append('rflags')
            if 'x86-flags-' in code or 'x86-imul-flags' in code or 'x86-shift' in code or 'x86-divide' in code: defs.append('rflags')
            if '(reg rsp)' in code: uses.append('rsp')
            if '(set-reg rsp' in code: defs.append('rsp')
            if 'x86-divide' in code: uses += ['rax', 'rdx']; defs += ['rax', 'rdx']
            if 'fp-environment' in effects: uses.append('mxcsr'); defs.append('mxcsr')
        elif self.name == 'arm64':
            if 'arm-condition' in code: uses.append('nzcv')
            if '(nzcv-' in code: defs.append('nzcv')
            if '(set-reg x30' in code: defs.append('x30')
            if 'fp-environment' in effects: uses.append('fpcr'); defs.append('fpsr')
        elif 'fp-environment' in effects:
            uses.append('fcsr'); defs.append('fcsr')
        self.add('instruction', name,
                 prop('doc', q(doc or asm)),
                 prop('requires', refs('feature', features)),
                 prop('operands', '\n      ' + '\n      '.join(operands) if operands else ''),
                 prop('encoding', prop('base', q(base)) + ''.join(f' (field {o} {d} {w} {s})' for o, d, w, s in fields)),
                 prop('pcode', code), prop('assembly', q(asm)), prop('effects', effects),
                 prop('modes', ref('mode', mode)), prop('implicit-use', refs('register', uses)),
                 prop('implicit-def', refs('register', defs)),
                 prop('schedule', ref('schedule', schedule)), prop('constraints', q(constraints)),
                 *(prop(k.replace('_', '-'), v) for k, v in extra.items()))

    def render(self):
        return (f'; ArchML v1: {self.name}. Generated by tools/generate_archml.py.\n'
                '; Concrete forms and extension coverage are listed explicitly below.\n'
                f'(archml 1 {self.name}\n' + '\n'.join(self.records) + '\n)\n')


def operand(name, bits, signed=False, scale=1, cls=None, access='read', exclude=()):
    return (f'({name} (kind {"register" if cls else "immediate"}) (bits {bits}) '
            f'(signed {str(signed).lower()}) (scale {scale}) (access {access})'
            + (f' (class {ref("regclass", cls)})' if cls else '')
            + (f' (exclude {" ".join(map(str, exclude))})' if exclude else '') + ')')


def read(name):
    return f'(read {name})'


def write(name, value):
    return f'(write {name} {value})'


def bv(op, width, *args):
    return f'(bv{op} {width} ' + ' '.join(args) + ')'


def parallel(*args):
    return '(parallel ' + ' '.join(args) + ')'


def common(p, baseline, abi, triple, sources):
    p.add('target', p.name, prop('bits', 64), prop('endian', 'little'),
          prop('triple', q(triple)), prop('default-features', refs('feature', baseline)),
          prop('default-abi', ref('abi', abi)), prop('sources', q(sources)),
          prop('semantics', q('P-code evaluates operands in the pre-instruction state. Parallel effects commit together after fault checks. Widths are bits; addresses and displacements are bytes. Each instruction has an implicit next-PC equal to PC plus encoded length. Unwritten state is preserved.')))
    p.add('coverage', 'compiler-profile', prop('status', 'concrete-forms-with-explicit-fallbacks'),
          prop('contract', q('Instruction records are executable encoding templates, not mnemonic families. Unlisted operand/addressing forms are unsupported by the encoder. Metadata-only extensions must not be selected. Legalization supplies scalar expansion or named runtime helpers for unsupported operations. This is a compiler profile, not an exhaustive ISA or privileged-system simulator.')),
          prop('abi-scope', q('ELF relocatable objects; static/small code model by default. ABI records describe aggregate/varargs rules for frontend ABI lowering. Object writer, linker and unwinder consume relocation/layout metadata.')))
    ops = {
        'parallel': (1, 64, 'effect', 'Evaluate every RHS in pre-state; commit nonconflicting writes together after all synchronous fault checks. Memory faults leave the architectural destination and PC unchanged. Conflicting writes are invalid.'),
        'read': (1, 1, 'value', 'Read a named instruction operand: register operands read the selected view; immediate operands return the supplied scaled signed/unsigned value. Zero registers read zero. Storage aliases and per-instruction vector write policies apply.'),
        'write': (2, 2, 'effect', 'Write a named destination operand, truncating to its architectural view width; apply register write policy. Read-only/discard registers ignore the write.'),
        'reg': (1, 1, 'value', 'Read the explicitly named implicit architectural register in pre-state.'),
        'set-reg': (2, 2, 'effect', 'Write an explicitly named implicit architectural register with its view policy.'),
        'const': (2, 2, 'value', 'Construct a bitvector of width argument 1 by reducing integer argument 2 modulo 2^width.'),
        'pc': (0, 0, 'value', 'Current instruction address, not the next instruction.'),
        'next-pc': (0, 0, 'value', 'PC plus concrete encoding length modulo address width.'),
        'jump': (1, 1, 'control', 'Set PC to target. Target alignment and executable mapping checks are architecture-specific precise exceptions.'),
        'branch': (2, 2, 'control', 'If boolean condition is true, jump to target; otherwise advance to next-PC.'),
        'nop': (0, 0, 'effect', 'No architectural state change except advancing PC.'),
        'trap': (1, 1, 'control', 'Raise the named synchronous exception; no normal fallthrough.'),
        'load': (4, 4, 'memory', 'Arguments width,address,endian,required-alignment. Read width/8 bytes with the named endian; access/translation/alignment checks precede all destination writes. Memory ordering follows the profile.'),
        'store': (5, 5, 'memory', 'Arguments width,address,value,endian,required-alignment. Write low width bits with precise checks before commit. Not implicitly atomic beyond the memory record guarantee.'),
        'sext': (3, 3, 'value', 'Arguments source-width,destination-width,value. Sign extend low source-width bits; destination >= source.'),
        'zext': (3, 3, 'value', 'Arguments source-width,destination-width,value. Zero extend low source-width bits; destination >= source.'),
        'extract': (3, 3, 'value', 'Arguments value,low-bit,width. Return the selected low-indexed bit slice.'),
        'deposit': (4, 4, 'value', 'Arguments old,value,low-bit,width. Replace only that bit slice in old.'),
        'eq': (2, 2, 'bool', 'Bitvector equality; operands must have equal width.'),
        'ne': (2, 2, 'bool', 'Bitvector inequality; operands must have equal width.'),
        'slt': (2, 2, 'bool', 'Signed two-complement less-than on equally sized bitvectors.'),
        'ult': (2, 2, 'bool', 'Unsigned less-than on equally sized bitvectors.'),
        'sge': (2, 2, 'bool', 'Signed greater-than-or-equal on equally sized bitvectors.'),
        'uge': (2, 2, 'bool', 'Unsigned greater-than-or-equal on equally sized bitvectors.'),
        'bool-int': (2, 2, 'value', 'Arguments width,boolean. Produce zero or one at width.'),
        'fence': (2, 2, 'memory', 'Order named predecessor and successor access sets. Compiler motion and hardware visibility both obey the target atomic record.'),
        'fp-bin': (5, 5, 'value', 'Arguments operation,IEEE-format,left,right,rounding-environment. Perform IEEE-754 arithmetic including signed zero, infinities and NaNs. Set target sticky exception flags; trap only if enabled. Target NaN propagation, flush modes and boxing policy come from vector/extension records.'),
        'vector-bin': (5, 5, 'value', 'Arguments operation,lane-format,lane-count,left,right. Apply lane-wise operation. Integer lanes wrap; floating lanes use the FP environment. No cross-lane carries.'),
        'x86-condition': (1, 1, 'bool', 'Decode condition nibble: 0 OF,2 CF,4 ZF,6 CF|ZF,8 SF,10 PF,12 SF!=OF,14 ZF|(SF!=OF); odd nibbles invert the preceding predicate.'),
        'arm-condition': (1, 1, 'bool', '0 Z,2 C,4 N,6 V,8 C&!Z,10 N==V,12 !Z&(N==V); odd values invert except 15, and 14/15 always true.'),
        'x86-flags-add': (3, 3, 'flags', 'Arguments width,a,b. r=(a+b) mod 2^w; CF=unsigned carry; OF=((~(a xor b)&(a xor r))>>(w-1))&1; AF=((a xor b xor r)>>4)&1; ZF=r==0; SF=msb(r); PF=even parity of low byte.'),
        'x86-flags-sub': (3, 3, 'flags', 'Arguments width,a,b. r=(a-b) mod 2^w; CF=unsigned a<b; OF=(((a xor b)&(a xor r))>>(w-1))&1; AF=((a xor b xor r)>>4)&1; ZF=r==0; SF=msb(r); PF=even parity low byte.'),
        'x86-flags-logic': (2, 2, 'flags', 'Arguments width,result. CF=OF=0; AF undefined/fresh nondeterministic; ZF=result==0; SF=msb(result); PF=even parity low byte. Undefined flags are not poison and cannot justify equality proofs.'),
        'x86-imul-flags': (3, 3, 'flags', 'Arguments width,a,b. CF=OF iff signed full product differs from sign-extension of low width bits. SF/ZF/AF/PF undefined.'),
        'x86-shift': (4, 4, 'effect', 'Arguments operation,width,destination-operand,count. Mask count to 5 bits for width32 or 6 for width64; zero count preserves destination and flags. For nonzero count set result and CF to last shifted bit, ZF/SF/PF from result, AF undefined; OF defined only for count1: SHL=msb(result) xor CF, SHR=old msb, SAR=0. Counts>1 leave OF undefined.'),
        'nzcv-add': (3, 3, 'flags', 'Arguments width,a,b. N=msb(sum), Z=sum==0, C=unsigned carry, V=signed overflow. Results computed modulo width.'),
        'nzcv-sub': (3, 3, 'flags', 'Arguments width,a,b. N=msb(difference), Z=difference==0, C=unsigned a>=b (no borrow), V=signed overflow.'),
        'nzcv-logic': (2, 2, 'flags', 'Arguments width,result. N=msb, Z=result==0, C=V=0.'),
        'amo': (5, 5, 'memory', 'Arguments operation,width,address,new-value,order-bits. Atomic read-modify-write linearizes at one point; returns old value. Order bit1 acquire, bit0 release. Natural alignment required. Faults do not commit. Word results sign-extend on RV64.'),
        'reserve-load': (3, 3, 'memory', 'Arguments width,address,order. Load and establish implementation-defined reservation granule containing address. Word results sign-extend. Natural alignment and access permissions required.'),
        'conditional-store': (4, 4, 'memory', 'Arguments width,address,value,order. Return 0 and store if reservation succeeds; otherwise nonzero and no write. Always clears reservation. Spurious failure is permitted; compiler must loop and obey forward-progress rules.'),
        'x86-xchg-memory': (3, 3, 'memory', 'Arguments width,address,new-value. Implicitly locked exchange; return old value, globally ordered atomic RMW. Does not change arithmetic flags.'),
    }
    for operation, description in [('add', 'modular addition'), ('sub', 'modular subtraction'),
                                   ('mul', 'low modular product'), ('and', 'bitwise AND'),
                                   ('or', 'bitwise OR'), ('xor', 'bitwise XOR'),
                                   ('shl', 'logical left shift'), ('lshr', 'logical right shift'),
                                   ('ashr', 'arithmetic right shift'), ('udiv', 'unsigned quotient'),
                                   ('sdiv', 'signed quotient rounded toward zero'),
                                   ('urem', 'unsigned remainder'), ('srem', 'signed remainder with dividend sign')]:
        extra = (' Shift count >= width yields zero for logical shifts and sign fill for arithmetic shift; instructions explicitly mask counts where required.' if 'sh' in operation else '')
        extra += (' Zero divisor yields all-ones quotient or dividend remainder; signed MIN/-1 yields MIN quotient and zero remainder. Targets with trapping division need separate trap checks.' if operation in ('udiv', 'sdiv', 'urem', 'srem') else '')
        ops['bv' + operation] = (3, 3, 'value', 'Arguments width,a,b: ' + description + '; inputs and result reduced modulo 2^width.' + extra)
    for name, (lo, hi, effect, semantics) in ops.items():
        p.add('pcode-op', name, prop('arity', f'{lo} {hi}'), prop('effect', effect), prop('semantics', q(semantics)))
    for name, bits, category in [('i1', 1, 'integer'), ('i8', 8, 'integer'), ('i16', 16, 'integer'),
                                  ('i32', 32, 'integer'), ('i64', 64, 'integer'), ('i128', 128, 'integer'),
                                  ('f32', 32, 'ieee-binary'), ('f64', 64, 'ieee-binary'), ('ptr', 64, 'pointer')]:
        p.add('type', name, prop('bits', bits), prop('kind', category), prop('alignment', min(max(1, bits // 8), 16)))
    p.add('resource', 'integer', prop('capacity', 1), prop('unit', 'issue-slots'))
    p.add('resource', 'memory', prop('capacity', 1), prop('unit', 'issue-slots'))
    p.add('resource', 'floating', prop('capacity', 1), prop('unit', 'issue-slots'))
    for name, latency, resource, barrier in [('alu', 1, 'integer', 'false'), ('mul', 4, 'integer', 'false'),
                                          ('div', 32, 'integer', 'false'), ('load', 4, 'memory', 'false'),
                                          ('store', 1, 'memory', 'false'), ('branch', 1, 'integer', 'true'),
                                          ('fp', 5, 'floating', 'false'), ('serial', 64, 'memory', 'true')]:
        p.add('schedule', name, prop('latency', latency), prop('throughput-cycles', 1),
              prop('uses', ref('resource', resource)), prop('barrier', barrier),
              prop('doc', q('Conservative generic tuning estimate, not an architectural timing guarantee. Memory aliasing, faults and data dependencies dominate legal motion.')))
    p.add('microarch', 'generic', prop('issue-width', 1), prop('model', 'conservative-in-order'),
          prop('schedules', refs('schedule', ['alu', 'mul', 'div', 'load', 'store', 'branch', 'fp', 'serial'])),
          prop('hazards', q('RAW, WAR and WAW dependencies; flags and implicit registers are resources. Never speculate trapping, volatile, atomic or serializing operations across control or memory barriers.')))
    p.add('legalize', 'wide-integer', prop('types', ref('type', 'i128')), prop('action', 'expand'),
          prop('recipe', q('add/sub: two i64 halves with explicit carry/borrow; multiply: four limb products; shifts: split at 64; compare: high signed/unsigned then low unsigned. Division and remainder call __divti3/__udivti3/__modti3/__umodti3 with target ABI.')))
    p.add('legalize', 'small-integer', prop('types', refs('type', ['i1', 'i8', 'i16'])), prop('action', 'promote'),
          prop('to', ref('type', 'i32')), prop('recipe', q('Zero/sign extend before widened operations according to IR; truncate stores/results. Mask i1. Signed compare/div/rem/arithmetic shift require sign extension. Preserve original-width overflow and poison semantics at the IR boundary.')))
    p.add('legalize', 'unsupported-vector', prop('action', 'scalarize'),
          prop('recipe', q('Split fixed vectors into independently legalized lanes. Preserve lane masks and inactive-lane merge/zero policy. Scalable vectors require an explicitly enabled scalable backend or a diagnostic, never silently assume a fixed length.')))
    p.add('legalize', 'runtime-fallbacks', prop('action', 'libcall'),
          prop('symbols', q('memcpy memmove memset; __divdi3/__udivdi3/__moddi3/__umoddi3 for i64 division/remainder when no legal machine form; __atomic_load/__atomic_store/__atomic_exchange/__atomic_compare_exchange for unsupported widths; fmod/fmodf, sqrt/sqrtf, conversions and compiler-rt helpers as required. Link the target-compatible runtime.')),
          prop('constraints', q('Honor overlap for memmove, volatile and atomic semantics, errno/fenv requirements, and exact ABI helper signatures. Unsupported operations without a legal expansion/runtime declaration must be diagnosed.')))
    p.add('rewrite', 'add-zero', prop('match', '(bvadd W X (const W 0))'), prop('replace', 'X'),
          prop('guards', q('Pure bitvector result; arithmetic flags dead, no memory/fault/volatile effects, matching widths. SSA poison behavior must already be discharged.')),
          prop('proof', ref('smt', 'bitvectors')))
    p.add('rewrite', 'double-xor', prop('match', '(bvxor W X X)'), prop('replace', '(const W 0)'),
          prop('guards', q('Identical defined operands at equal width; flags dead; do not duplicate or remove observable loads.')),
          prop('proof', ref('smt', 'bitvectors')))
    p.add('rewrite', 'branch-inversion', prop('recipe', q('Invert predicate and exchange CFG successors; preserve fallthrough edge probabilities, exception edges, target reachability and relocation kind.')))
    p.add('smt', 'bitvectors', prop('logic', 'QF_AUFBV'), prop('state', q('Registers are storage bitvectors; memory is Array[addr64,byte8]. Subregister writes use extract/concat. Separate memory tokens and effect order from pure values.')),
          prop('preconditions', q('Equal input widths; defined inputs; alignment and no-fault hypotheses explicit. Undefined architectural flags are fresh independent values. Never treat undefined as zero or assume poison can be concretized.')),
          prop('objective', q('Prove equivalence of live outputs, memory effects, traps and control flow under guards before comparing size/latency/register-pressure costs. Timeouts or unknown solver results reject a rewrite.')))
    p.add('smt', 'floating-point', prop('logic', 'QF_FP'), prop('preconditions', q('Model rounding modes, signed zero, NaNs, infinities, exceptions and target flush/NaN propagation. Reassociation requires explicit fast-math permissions. Bitvector identities do not prove IEEE-754 transformations.')))
    p.add('legalize', 'floating-transcendentals', prop('types', refs('type', ['f32', 'f64'])), prop('action', 'libcall'),
          prop('recipe', q('sin/cos/tan/exp/log/pow/sqrt/fmod and their f-suffixed f32 variants use the declared target C runtime signatures. Preserve errno and fenv observability unless IR flags permit otherwise. IEEE scalar arithmetic uses native forms only with enabled FP state; otherwise use compiler-rt soft-float helpers.')))
    p.add('legalize', 'unaligned-access', prop('action', 'expand'),
          prop('recipe', q('Where normal unaligned accesses are unavailable, assemble/disassemble little-endian bytes using shifts/OR and byte loads/stores. Do not split atomic or volatile accesses unless the execution environment explicitly allows it; otherwise call the appropriate runtime or diagnose.')))
    p.add('rewrite', 'load-store-combine', prop('recipe', q('Combine adjacent nonvolatile, nonatomic accesses only with proven alias, alignment, bounds, endianness and no-extra-fault equivalence; retain debug locations and memory ordering tokens. A shorter sequence is not automatically equivalent.')))


def amd64():
    p = Profile('amd64')
    common(p, ['base', 'sse', 'sse2'], 'sysv', 'x86_64-unknown-linux-gnu',
           'Intel SDM Volumes 1,2,3; AMD APM Volumes 1-3; System V AMD64 psABI; Microsoft x64 ABI. Encodings here target long mode without APX.')
    for name, desc, deps in [('base', 'Long-mode integer baseline', []), ('sse', 'XMM single-precision SIMD', ['base']),
                              ('sse2', 'Scalar/vector double and integer SIMD; x86-64 baseline', ['sse']),
                              ('avx', 'VEX, YMM and OSXSAVE/XCR0 XMM+YMM state required', ['sse2']),
                              ('avx2', '256-bit integer SIMD', ['avx']), ('fma', 'Single-rounding fused multiply-add', ['avx']),
                              ('avx512f', 'EVEX, opmask and ZMM state enabled in XCR0', ['avx2']),
                              ('bmi1', 'Bit manipulation set 1', ['base']), ('bmi2', 'Bit manipulation set 2', ['base']),
                              ('popcnt', 'Population count', ['base']), ('aes', 'AES-NI rounds', ['sse2']),
                              ('sha', 'SHA acceleration', ['sse2']), ('x87', '80-bit register stack floating point', ['base']),
                              ('cet', 'IBT and shadow-stack runtime enablement required', ['base'])]:
        p.feature(name, desc, deps)
    gpr = ['rax', 'rcx', 'rdx', 'rbx', 'rsp', 'rbp', 'rsi', 'rdi'] + [f'r{i}' for i in range(8, 16)]
    low32 = ['eax', 'ecx', 'edx', 'ebx', 'esp', 'ebp', 'esi', 'edi'] + [f'r{i}d' for i in range(8, 16)]
    low16 = ['ax', 'cx', 'dx', 'bx', 'sp', 'bp', 'si', 'di'] + [f'r{i}w' for i in range(8, 16)]
    low8 = ['al', 'cl', 'dl', 'bl', 'spl', 'bpl', 'sil', 'dil'] + [f'r{i}b' for i in range(8, 16)]
    dwarfs = [0, 2, 1, 3, 7, 6, 4, 5] + list(range(8, 16))
    for i, name in enumerate(gpr):
        p.storage(name, 64)
        p.reg(name, 64, name, i, dwarfs[i])
        p.reg(low32[i], 32, name, i, write='zero-extend')
        p.reg(low16[i], 16, name, i, write='preserve')
        p.reg(low8[i], 8, name, i, write='preserve')
    for i, name in enumerate(['ah', 'ch', 'dh', 'bh']):
        p.reg(name, 8, gpr[i], i+4, offset=8, write='preserve')
    for name, bits, dwarf in [('rip', 64, 16), ('rflags', 64, 49), ('mxcsr', 32, 64), ('fsbase', 64, 58), ('gsbase', 64, 59)]:
        p.storage(name, bits); p.reg(name, bits, name, 0, dwarf)
    for name, bit in [('cf', 0), ('pf', 2), ('af', 4), ('zf', 6), ('sf', 7), ('df', 10), ('of', 11)]:
        p.reg(name, 1, 'rflags', 0, offset=bit, write='preserve')
    for i in range(32):
        p.storage(f'zmm{i}', 512)
        p.reg(f'zmm{i}', 512, f'zmm{i}', i)
        p.reg(f'ymm{i}', 256, f'zmm{i}', i, write='preserve')
        p.reg(f'xmm{i}', 128, f'zmm{i}', i, 17+i if i < 16 else 67+i-16, write='preserve')
    for i in range(8):
        p.storage(f'st{i}', 80); p.reg(f'st{i}', 80, f'st{i}', i, 33+i)
        p.reg(f'mm{i}', 64, f'st{i}', i, 41+i, write='preserve')
        p.storage(f'k{i}', 64); p.reg(f'k{i}', 64, f'k{i}', i, 118+i)
    p.regclass('GR64', gpr, 64, ['rsp'], two_address='true')
    p.regclass('GR32', low32, 32, ['esp'], two_address='true')
    p.regclass('GR16', low16, 16, ['sp'], two_address='true')
    p.regclass('GR8REX', low8, 8, ['spl'], high_byte_forbidden='true')
    p.regclass('XMM', [f'xmm{i}' for i in range(16)], 128)
    p.regclass('YMM', [f'ymm{i}' for i in range(16)], 256)
    p.regclass('ZMM', [f'zmm{i}' for i in range(32)], 512)
    p.regclass('MASK', [f'k{i}' for i in range(1, 8)], 64)
    p.add('mode', 'long64', prop('address-bits', 64), prop('default-operand-bits', 32), prop('privilege', 'cpl3'),
          prop('rules', q('REX.W selects 64-bit operands; 32-bit GPR writes zero upper32; 16/8 writes preserve. Any REX forbids AH/BH/CH/DH. Instruction length <=15. Canonical addresses enforced by current LA48/LA57 mode.')))
    p.add('memory', 'normal', prop('model', 'TSO'), prop('address-bits', 64), prop('endian', 'little'),
          prop('alignment', q('Unaligned scalar accesses supported on ordinary memory; page crossings may fault. Naturally aligned 1/2/4/8-byte ordinary accesses are atomic under architectural normal-memory conditions; do not extrapolate to MMIO or split accesses.')),
          prop('ordering', q('Store->load reordering via store buffer is possible. Compiler must preserve language atomics; SFENCE/LFENCE/MFENCE and LOCKed RMW have distinct architectural scope.')))
    p.add('addressing', 'sib', prop('formula', '(base-plus-scaled-index-plus-displacement base index scale displacement)'),
          prop('scales', '1 2 4 8'), prop('displacement-bits', '8 32'),
          prop('constraints', q('SIB index encoding4 means none unless REX.X selects r12. Mod00 base5 uses disp32; RIP-relative uses ModRM rm5 without SIB. Concrete memory forms here use Mod10 SIB no-index and disp32, including RSP/R12 and RBP/R13.')))
    p.add('atomic', 'language', prop('loads', 'mov'), prop('stores-release', 'mov'), prop('stores-seq-cst', 'xchg-or-mfence'),
          prop('rmw', q('LOCK arithmetic/CMPXCHG or implicit-lock XCHG; exact width/natural alignment and memory type required. Wider atomics use runtime helpers. Never use volatile as an atomic substitute.')))
    p.add('exception', 'precise', prop('kinds', 'divide-error invalid-opcode general-protection page-fault alignment-check breakpoint'),
          prop('rules', q('Faulting instruction PC retained for restart; traps such as INT3 report following PC. Integer divide by zero or quotient overflow raises #DE. Masked FP exceptions set MXCSR flags; unmasked exceptions trap.')))
    p.add('vector', 'simd', prop('widths', '128 256 512'), prop('lanes', 'i8 i16 i32 i64 f32 f64'),
          prop('rules', q('Legacy SSE scalar arithmetic preserves destination bits127:lane-width and all bits above127; packed legacy writes low128 and preserves above128. VEX/EVEX writes zero upper vector state according to encoding; AVX512 masks merge or zero and can suppress faults per lane. MXCSR controls rounding, exception masks, DAZ and FTZ.')))
    p.add('predication', 'flags', prop('conditions', 'o no b ae e ne be a s ns p np l ge le g'),
          prop('invert', 'xor-1'), prop('flags', refs('register', ['cf', 'pf', 'zf', 'sf', 'of'])))
    p.add('syntax', 'intel', prop('assembler', 'gas-intel-or-nasm'), prop('operand-order', 'destination-first'),
          prop('rules', q('GAS: .intel_syntax noprefix; brackets for memory, explicit BYTE/WORD/DWORD/QWORD PTR when ambiguous; registers bare. NASM directives differ; instruction templates use Intel operands.')))
    p.add('syntax', 'att', prop('assembler', 'gas'), prop('operand-order', 'source-first'),
          prop('rules', q('Registers prefixed %, immediates $, memory displacement(base,index,scale). Add b/w/l/q suffix by operand width. Reverse ordinary binary Intel operand order; do not blindly reverse multi-immediate instructions. Indirect CALL/JMP require *.')))
    p.add('abi', 'sysv', prop('stack-align', 16), prop('red-zone', 128), prop('stack-pointer', ref('register', 'rsp')),
          prop('integer-args', refs('register', ['rdi', 'rsi', 'rdx', 'rcx', 'r8', 'r9'])),
          prop('float-args', refs('register', [f'xmm{i}' for i in range(8)])), prop('returns', refs('register', ['rax', 'rdx', 'xmm0', 'xmm1'])),
          prop('callee-saved', refs('register', ['rbx', 'rbp', 'r12', 'r13', 'r14', 'r15', 'rsp'])),
          prop('rules', q('RSP%16=8 at ordinary entry; align to16 before CALL. Red zone only for user-space leaf storage, disabled for kernel/interrupt environments. DF clear at calls. Classify aggregates into at most two eightbytes using INTEGER/SSE/SSEUP/X87/X87UP/COMPLEX_X87/MEMORY merging rules; MEMORY return uses hidden RDI pointer also returned in RAX. Variadic AL gives used vector arg count 0..8; va_list has gp_offset,fp_offset,overflow_arg_area,reg_save_area. Stack args right-to-left with ABI alignment. All other GPRs and XMM registers caller-saved; MXCSR control bits preserved, status caller-saved.')))
    p.add('abi', 'win64', prop('stack-align', 16), prop('shadow-space', 32), prop('red-zone', 0),
          prop('integer-args', refs('register', ['rcx', 'rdx', 'r8', 'r9'])), prop('float-args', refs('register', ['xmm0', 'xmm1', 'xmm2', 'xmm3'])),
          prop('callee-saved', refs('register', ['rbx', 'rbp', 'rdi', 'rsi', 'rsp', 'r12', 'r13', 'r14', 'r15']+[f'xmm{i}' for i in range(6, 16)])),
          prop('rules', q('Four positional slots shared between GPR/XMM classes, caller allocates32-byte home space. Variadic FP duplicated into matching integer slot. Small 1/2/4/8-byte aggregates pass as integers; other aggregates indirectly. Upper YMM/ZMM halves volatile. Use Windows unwind directives and stack probing for large allocations.')))
    p.add('layout', 'branches', prop('alignment', 1), prop('max-instruction-bytes', 15), prop('short', 'signed8-bytes-from-next-pc'),
          prop('near', 'signed32-bytes-from-next-pc'), prop('relax', q('Jcc rel8 -> Jcc rel32 -> inverted short Jcc over indirect absolute jump. JMP/CALL rel32 out-of-range: materialize target in reserved scratch R11 then indirect transfer; record clobber and relocation. RIP literal reach is signed32 from next PC.')))
    for name, bits, formula in [('R_X86_64_PC32', 32, 'S+A-P'), ('R_X86_64_PLT32', 32, 'L+A-P'),
                                  ('R_X86_64_64', 64, 'S+A'), ('R_X86_64_GOTPCREL', 32, 'G+GOT+A-P')]:
        p.add('relocation', name, prop('bits', bits), prop('formula', q(formula)), prop('rules', q('ELF64 RELA; P is relocation-field address. PC-relative instruction immediates commonly use addend -4 to refer to next-PC. Check signed overflow; do not truncate.')))
    rr_fields = [('dst', 16, 3, 0), ('dst', 0, 1, 3), ('src', 19, 3, 0), ('src', 2, 1, 3)]
    for width in (32, 64):
        prefix = '48' if width == 64 else '40'
        cls = f'GR{width}'
        ops = [operand('dst', 4, cls=cls, access='read-write'), operand('src', 4, cls=cls)]
        for name, opcode, operation in [('add', '01', 'add'), ('sub', '29', 'sub'), ('and', '21', 'and'),
                                        ('or', '09', 'or'), ('xor', '31', 'xor'), ('cmp', '39', 'sub'), ('test', '85', 'and'), ('mov', '89', None)]:
            value = bv(operation, width, read('dst'), read('src')) if operation else read('src')
            code = write('dst', value)
            if operation:
                flag = f'(x86-flags-{operation} {width} {read("dst")} {read("src")})' if operation in ('add', 'sub') else f'(x86-flags-logic {width} {value})'
                code = flag if name in ('cmp', 'test') else parallel(code, flag)
            form_ops = [operand('dst', 4, cls=cls, access='read' if name in ('cmp', 'test') else 'write' if name == 'mov' else 'read-write'), ops[1]]
            p.instruction(f'{name}{width}-rr', prefix+opcode+'c0', form_ops, rr_fields, code,
                          f'{name} {{dst}}, {{src}}', effects='flags' if operation else 'pure',
                          constraints='Two-address destination; input dst tied to output except MOV. All flags modeled; implicit RFLAGS dependency.')
        for name, extension, operation in [('add', 0, 'add'), ('or', 1, 'or'), ('and', 4, 'and'), ('sub', 5, 'sub'), ('xor', 6, 'xor'), ('cmp', 7, 'sub')]:
            value = bv(operation, width, read('dst'), read('imm'))
            flag = f'(x86-flags-{operation} {width} {read("dst")} {read("imm")})' if operation in ('add', 'sub') else f'(x86-flags-logic {width} {value})'
            code = flag if name == 'cmp' else parallel(write('dst', value), flag)
            p.instruction(f'{name}{width}-ri', prefix+'81'+f'{0xc0+extension*8:02x}'+'00000000',
                          [operand('dst', 4, cls=cls, access='read' if name == 'cmp' else 'read-write'), operand('imm', 32, signed=width == 64)], [('dst', 16, 3, 0), ('dst', 0, 1, 3), ('imm', 24, 32, 0)],
                          code, f'{name} {{dst}}, {{imm}}', effects='flags')
        p.instruction(f'mov{width}-ri', prefix+'b8'+'00'*(width//8),
                      [operand('dst', 4, cls=cls, access='write'), operand('imm', width)],
                      [('dst', 8, 3, 0), ('dst', 0, 1, 3), ('imm', 16, width, 0)], write('dst', read('imm')), 'mov {dst}, {imm}')
        for name, ext in [('shl', 4), ('shr', 5), ('sar', 7)]:
            p.instruction(f'{name}{width}-ri', prefix+'c1'+f'{0xc0+ext*8:02x}'+'00',
                          [ops[0], operand('count', 8)], [('dst', 16, 3, 0), ('dst', 0, 1, 3), ('count', 24, 8, 0)],
                          f'(x86-shift {name} {width} dst {read("count")})', f'{name} {{dst}}, {{count}}', effects='flags')
        p.instruction(f'imul{width}-rr', prefix+'0fafc0', ops,
                      [('dst', 27, 3, 0), ('dst', 2, 1, 3), ('src', 24, 3, 0), ('src', 0, 1, 3)],
                      parallel(write('dst', bv('mul', width, read('dst'), read('src'))), f'(x86-imul-flags {width} {read("dst")} {read("src")})'),
                      'imul {dst}, {src}', effects='flags', schedule='mul')
        for name, opcode in [('load', '8b'), ('store', '89'), ('lea', '8d')]:
            address = bv('add', 64, read('base'), read('disp'))
            code = write('reg', f'(load {width} {address} little 1)') if name == 'load' else f'(store {width} {address} {read("reg")} little 1)' if name == 'store' else write('reg', address)
            p.instruction(f'{name}{width}-base-disp32', prefix+opcode+'8420'+'00000000',
                          [operand('reg', 4, cls=cls, access='read' if name == 'store' else 'write'), operand('base', 4, cls='GR64'), operand('disp', 32, True)],
                          [('reg', 19, 3, 0), ('reg', 2, 1, 3), ('base', 24, 3, 0), ('base', 0, 1, 3), ('disp', 32, 32, 0)], code,
                          ('mov {reg}, [{base}+{disp}]' if name == 'load' else 'mov [{base}+{disp}], {reg}' if name == 'store' else 'lea {reg}, [{base}+{disp}]'),
                          effects='memory' if name != 'lea' else 'pure', schedule=name if name != 'lea' else 'alu')
    for name, opcode, delta in [('push64', '50', -8), ('pop64', '58', 8)]:
        addr = bv('sub', 64, '(reg rsp)', '(const 64 8)') if delta < 0 else '(reg rsp)'
        code = parallel(f'(store 64 {addr} {read("reg")} little 1)', f'(set-reg rsp {addr})') if delta < 0 else parallel(write('reg', '(load 64 (reg rsp) little 1)'), f'(set-reg rsp {bv("add",64,"(reg rsp)","(const 64 8)")})')
        p.instruction(name, '40'+opcode, [operand('reg', 4, cls='GR64', access='read' if delta < 0 else 'write', exclude=(4,) if delta > 0 else ())],
                      [('reg', 8, 3, 0), ('reg', 0, 1, 3)], code, name[:-2]+' {reg}', effects='memory', schedule='store' if delta < 0 else 'load',
                      constraints='POP destination must not be RSP in this profile; PUSH RSP reads pre-state RSP.')
    p.instruction('ret', 'c3', [], [], parallel('(jump (load 64 (reg rsp) little 1))', f'(set-reg rsp {bv("add",64,"(reg rsp)","(const 64 8)")})'), 'ret', effects='control memory', schedule='branch')
    for name, modrm in [('jmp-reg', 'e0'), ('call-reg', 'd0')]:
        code = f'(jump {read("target")})'
        if name == 'call-reg':
            addr = bv('sub', 64, '(reg rsp)', '(const 64 8)')
            code = parallel(code, f'(store 64 {addr} (next-pc) little 1)', f'(set-reg rsp {addr})')
        p.instruction(name, '40ff'+modrm, [operand('target', 4, cls='GR64')], [('target', 16, 3, 0), ('target', 0, 1, 3)], code,
                      name.split('-')[0]+' {target}', effects='control', schedule='branch')
    for width, opcode in [(8, 'b6'), (16, 'b7')]:
        addr = bv('add', 64, read('base'), read('disp'))
        for signed in (False, True):
            op = ('be' if width == 8 else 'bf') if signed else opcode
            p.instruction(f'load{width}-'+('signed' if signed else 'unsigned'), '480f'+op+'8420'+'00000000',
                          [operand('reg', 4, cls='GR64', access='write'), operand('base', 4, cls='GR64'), operand('disp', 32, True)],
                          [('reg', 27, 3, 0), ('reg', 2, 1, 3), ('base', 32, 3, 0), ('base', 0, 1, 3), ('disp', 40, 32, 0)],
                          write('reg', f'({"sext" if signed else "zext"} {width} 64 (load {width} {addr} little 1))'),
                          ('movsx' if signed else 'movzx')+f' {{reg}}, {"byte" if width == 8 else "word"} ptr [{{base}}+{{disp}}]', effects='memory', schedule='load')
        prefix = '40' if width == 8 else '6640'
        shift = 0 if width == 8 else 8
        p.instruction(f'store{width}-base-disp32', prefix+('88' if width == 8 else '89')+'8420'+'00000000',
                      [operand('reg', 4, cls='GR8REX' if width == 8 else 'GR16'), operand('base', 4, cls='GR64'), operand('disp', 32, True)],
                      [('reg', 19+shift, 3, 0), ('reg', 2+shift, 1, 3), ('base', 24+shift, 3, 0), ('base', shift, 1, 3), ('disp', 32+shift, 32, 0)],
                      f'(store {width} {addr} {read("reg")} little 1)', 'mov [{base}+{disp}], {reg}', effects='memory', schedule='store')
    p.add('pcode-op', 'x86-divide', prop('arity', '3 3'), prop('effect', 'registers flags trap'),
          prop('semantics', q('Arguments signedness,width,divisor. Dividend is concatenated RDX:RAX at width64 or EDX:EAX at width32; signed interpretation applies to full2*width dividend. Zero divisor or quotient not fitting destination raises #DE before any writes. Otherwise quotient to RAX/EAX and remainder to RDX/EDX; signed remainder has dividend sign. Arithmetic flags undefined.')))
    for signed, ext in [(False, 6), (True, 7)]:
        p.instruction('idiv64' if signed else 'div64', '48f7'+f'{0xc0+ext*8:02x}', [operand('src', 4, cls='GR64')],
                      [('src', 16, 3, 0), ('src', 0, 1, 3)], f'(x86-divide {"signed" if signed else "unsigned"} 64 {read("src")})',
                      ('idiv' if signed else 'div')+' {src}', effects='implicit-registers flags trap', schedule='div',
                      constraints='RAX/RDX fixed implicit input/output; divisor must not alias overwritten setup registers. Signed setup sign-extends RAX into RDX; unsigned setup clears RDX.')
    for name, opcode, bits in [('jmp-rel8', 'eb', 8), ('jmp-rel32', 'e9', 32), ('call-rel32', 'e8', 32)]:
        target = bv('add', 64, '(next-pc)', read('disp'))
        code = f'(jump {target})'
        if name.startswith('call'):
            addr = bv('sub', 64, '(reg rsp)', '(const 64 8)')
            code = parallel(code, f'(store 64 {addr} (next-pc) little 1)', f'(set-reg rsp {addr})')
        p.instruction(name, opcode+'00'*(bits//8), [operand('disp', bits, True)], [('disp', 8, bits, 0)], code,
                      name.split('-')[0]+' {target}', effects='control', schedule='branch')
    cc = ['o', 'no', 'b', 'ae', 'e', 'ne', 'be', 'a', 's', 'ns', 'p', 'np', 'l', 'ge', 'le', 'g']
    for i, cond in enumerate(cc):
        for bits in (8, 32):
            prefix = f'{0x70+i:02x}' if bits == 8 else f'0f{0x80+i:02x}'
            p.instruction(f'j{cond}-rel{bits}', prefix+'00'*(bits//8), [operand('disp', bits, True)], [('disp', len(prefix)*4, bits, 0)],
                          f'(branch (x86-condition {i}) {bv("add",64,"(next-pc)",read("disp"))})', f'j{cond} {{target}}', effects='control flags-read', schedule='branch')
        p.instruction(f'set{cond}', f'400f{0x90+i:02x}c0', [operand('dst', 4, cls='GR8REX', access='write')],
                      [('dst', 24, 3, 0), ('dst', 0, 1, 3)], write('dst', f'(bool-int 8 (x86-condition {i}))'), f'set{cond} {{dst}}', effects='flags-read')
    for name, opcode in [('addsd', '58'), ('subsd', '5c'), ('mulsd', '59'), ('divsd', '5e')]:
        value = f'(fp-bin {name[:-2]} f64 (extract {read("dst")} 0 64) (extract {read("src")} 0 64) mxcsr)'
        p.instruction(name, 'f2400f'+opcode+'c0', [operand('dst', 4, cls='XMM', access='read-write'), operand('src', 4, cls='XMM')],
                      [('dst', 35, 3, 0), ('dst', 10, 1, 3), ('src', 32, 3, 0), ('src', 8, 1, 3)],
                      write('dst', f'(deposit {read("dst")} {value} 0 64)'), name+' {dst}, {src}', features=('sse2',), effects='fp-environment', schedule='fp')
    p.instruction('movsd-rr', 'f2400f10c0', [operand('dst', 4, cls='XMM', access='read-write'), operand('src', 4, cls='XMM')],
                  [('dst', 35, 3, 0), ('dst', 10, 1, 3), ('src', 32, 3, 0), ('src', 8, 1, 3)],
                  write('dst', f'(deposit {read("dst")} (extract {read("src")} 0 64) 0 64)'), 'movsd {dst}, {src}', features=('sse2',))
    for load in (True, False):
        address = bv('add', 64, read('base'), read('disp'))
        code = write('reg', f'(zext 64 128 (load 64 {address} little 1))') if load else f'(store 64 {address} (extract {read("reg")} 0 64) little 1)'
        p.instruction('movsd-load' if load else 'movsd-store', 'f2400f'+('10' if load else '11')+'8420'+'00000000',
                      [operand('reg', 4, cls='XMM', access='write' if load else 'read'), operand('base', 4, cls='GR64'), operand('disp', 32, True)],
                      [('reg', 35, 3, 0), ('reg', 10, 1, 3), ('base', 40, 3, 0), ('base', 8, 1, 3), ('disp', 48, 32, 0)], code,
                      'movsd {reg}, [{base}+{disp}]' if load else 'movsd [{base}+{disp}], {reg}', features=('sse2',), effects='memory', schedule='load' if load else 'store')
    for to_vector in (True, False):
        p.instruction('movq-to-xmm' if to_vector else 'movq-from-xmm', '66480f'+('6e' if to_vector else '7e')+'c0',
                      [operand('vec', 4, cls='XMM', access='write' if to_vector else 'read'), operand('gpr', 4, cls='GR64', access='read' if to_vector else 'write')],
                      [('vec', 35, 3, 0), ('vec', 10, 1, 3), ('gpr', 32, 3, 0), ('gpr', 8, 1, 3)],
                      write('vec', f'(zext 64 128 {read("gpr")})') if to_vector else write('gpr', f'(extract {read("vec")} 0 64)'),
                      'movq {vec}, {gpr}' if to_vector else 'movq {gpr}, {vec}', features=('sse2',))
    p.instruction('addps', '400f58c0', [operand('dst', 4, cls='XMM', access='read-write'), operand('src', 4, cls='XMM')],
                  [('dst', 27, 3, 0), ('dst', 2, 1, 3), ('src', 24, 3, 0), ('src', 0, 1, 3)],
                  write('dst', f'(vector-bin add f32 4 {read("dst")} {read("src")})'), 'addps {dst}, {src}', features=('sse',), effects='fp-environment', schedule='fp')
    for name, base, code in [('nop', '90', '(nop)'), ('int3', 'cc', '(trap breakpoint)'), ('ud2', '0f0b', '(trap invalid-opcode)'),
                              ('mfence', '0faef0', '(fence all all)'), ('lfence', '0faee8', '(fence load load)'), ('sfence', '0faef8', '(fence store store)')]:
        p.instruction(name, base, [], [], code, name, effects='barrier' if 'fence' in name else 'control', schedule='serial')
    for extension in ['avx', 'avx2', 'avx512f', 'fma', 'bmi1', 'bmi2', 'popcnt', 'aes', 'sha', 'x87', 'cet']:
        p.add('extension', extension, prop('requires', ref('feature', extension)), prop('coverage', 'metadata-only'),
              prop('lowering', ref('legalize', 'unsupported-vector' if extension.startswith('avx') else 'runtime-fallbacks')),
              prop('semantics', q('Enable only with a concrete instruction form and full state/OS contract. Extension feature presence alone does not add encoding support. See target sources for all unlisted forms.')))
    for ir, form in [('add', 'add64-rr'), ('sub', 'sub64-rr'), ('mul', 'imul64-rr'), ('and', 'and64-rr'), ('or', 'or64-rr'), ('xor', 'xor64-rr'), ('load', 'load64-base-disp32'), ('store', 'store64-base-disp32')]:
        p.add('selection', ir, prop('pattern', f'(ir-op {ir} i64)'), prop('type', ref('type', 'i64')), prop('instruction', ref('instruction', form)), prop('cost', 1),
              prop('constraints', q('Use legalized operands. Preserve live RFLAGS and two-address ties; reserve scratch registers for materialization and spills.')))
    return p


def arm64():
    p = Profile('arm64')
    common(p, ['base', 'fp', 'simd'], 'aapcs64', 'aarch64-unknown-linux-gnu', 'Arm ARM A-profile A64 instruction descriptions; AAPCS64 and AAELF64. Little-endian EL0 compiler profile.')
    for name, desc, deps in [('base', 'A64 integer execution', []), ('fp', 'IEEE scalar floating point', ['base']),
                              ('simd', 'Advanced SIMD / NEON', ['fp']), ('lse', 'Large System Extensions atomics', ['base']),
                              ('sve', 'Scalable vectors 128..2048 bits', ['simd']), ('sve2', 'SVE2 integer extensions', ['sve']),
                              ('pauth', 'Pointer authentication with key/domain context', ['base']), ('bti', 'Branch target identification', ['base']),
                              ('crypto', 'AES/SHA polynomial operations', ['simd']), ('mte', 'Memory tagging with runtime policy', ['base'])]:
        p.feature(name, desc, deps)
    for i in range(31):
        p.storage(f'x{i}', 64); p.reg(f'x{i}', 64, f'x{i}', i, i); p.reg(f'w{i}', 32, f'x{i}', i, write='zero-extend')
    for name in ['sp', 'zero', 'pc', 'nzcv', 'fpcr', 'fpsr']:
        p.storage(name, 64 if name in ('sp', 'zero', 'pc') else 32)
    p.reg('sp', 64, 'sp', 31, 31); p.reg('wsp', 32, 'sp', 31, write='zero-extend')
    p.reg('xzr', 64, 'zero', 31, write='discard'); p.reg('wzr', 32, 'zero', 31, write='discard')
    for name in ['pc', 'nzcv', 'fpcr', 'fpsr']:
        p.reg(name, 64 if name == 'pc' else 32, name, 0, 32 if name == 'pc' else None)
    for i in range(32):
        p.storage(f'z{i}', 2048, True); p.reg(f'z{i}', 2048, f'z{i}', i)
        for prefix, width in [('v', 128), ('d', 64), ('s', 32), ('h', 16), ('b', 8)]:
            p.reg(f'{prefix}{i}', width, f'z{i}', i, 64+i if prefix == 'v' else None, write='zero-extend')
    for i in range(16):
        p.storage(f'p{i}', 256, True); p.reg(f'p{i}', 256, f'p{i}', i)
    for width, prefix, zero in [(64, 'x', 'xzr'), (32, 'w', 'wzr')]:
        p.regclass(f'GR{width}', [f'{prefix}{i}' for i in range(31)]+[zero], width, [f'{prefix}18', zero])
        p.regclass(f'GR{width}SP', [f'{prefix}{i}' for i in range(31)]+['sp' if width == 64 else 'wsp'], width,
                   [f'{prefix}18', 'sp' if width == 64 else 'wsp'])
    p.regclass('FPR64', [f'd{i}' for i in range(32)], 64)
    p.regclass('FPR32', [f's{i}' for i in range(32)], 32)
    p.regclass('V128', [f'v{i}' for i in range(32)], 128)
    p.regclass('Z', [f'z{i}' for i in range(32)], 2048, scalable='true')
    p.regclass('P', [f'p{i}' for i in range(16)], 256, scalable='true')
    for level in range(4):
        p.add('mode', f'el{level}', prop('address-bits', 64), prop('instruction-align', 4), prop('privilege', level),
              prop('rules', q('A64 instructions remain little-endian. Data endianness and translation granules are execution-context settings; this profile selects little-endian data. Register31 is SP or ZR according to the operand class, never a single interchangeable register.')))
    p.add('memory', 'normal', prop('model', 'weakly-ordered'), prop('endian', 'little'), prop('address-bits', 64),
          prop('rules', q('Normal memory allows many unaligned scalar accesses subject to alignment controls; device memory, exclusive and atomic operations require their specified alignment. Translation granules4/16/64KiB, TBI/MTE/PAC address bits and VA size are OS configuration, not inferred from pointer width.')))
    p.add('addressing', 'base-offset', prop('scaled', 'unsigned12-times-access-size'), prop('unscaled', 'signed9-bytes'),
          prop('register-offset', 'extend-and-optional-scale'), prop('rules', q('SP base requires architectural stack alignment. Pre/post-index writeback has overlap restrictions. Concrete forms use unsigned scaled offsets; materialize other addresses with ADD/SUB or scratch registers.')))
    p.add('atomic', 'language', prop('orders', 'relaxed acquire release acq-rel seq-cst'),
          prop('recipes', q('Acquire load LDAR; release store STLR; RMW via LDXR/STXR retry with acquire/release variants or enabled LSE forms. Use DMB ISH where the language mapping requires it. Exclusive loops have forward-progress restrictions; no unrelated stores between load/store-exclusive. Wider/unaligned atomics use runtime helpers.')))
    p.add('exception', 'precise', prop('kinds', 'instruction-abort data-abort alignment undefined svc brk fp'),
          prop('rules', q('ELR_ELx/SPSR_ELx/ESR_ELx record restart PC, old status and syndrome at target EL. BRK/SVC exception PC conventions differ by exception. Fault checks precede result/writeback. Integer divide by zero returns zero and does not trap.')))
    p.add('vector', 'neon-sve', prop('fixed-bits', 128), prop('scalable-min-bits', 128), prop('scalable-max-bits', 2048),
          prop('rules', q('A64 writes to scalar FP/SIMD views zero the remaining architectural SIMD destination bits as specified; full scalable state rules depend on streaming/SVE mode. SVE predicates have one bit per byte with wider-element spacing; inactive elements merge or zero according to instruction. FPCR controls rounding, FZ and DN; FPSR holds cumulative exceptions.')))
    p.add('predication', 'nzcv', prop('conditions', 'eq ne cs cc mi pl vs vc hi ls ge lt gt le al'), prop('invert', 'xor-1-except-al'), prop('flags', ref('register', 'nzcv')))
    p.add('syntax', 'gas', prop('operand-order', 'destination-first'), prop('rules', q('Registers x/w/v/s/d; immediates #; memory [base,#offset], preindex !, postindex separate immediate. ELF ADRP :pg_hi21: and ADD :lo12: relocations; .p2align2 for code.')))
    p.add('abi', 'aapcs64', prop('stack-align', 16), prop('red-zone', 0), prop('stack-pointer', ref('register', 'sp')),
          prop('integer-args', refs('register', [f'x{i}' for i in range(8)])), prop('float-args', refs('register', [f'v{i}' for i in range(8)])),
          prop('callee-saved', refs('register', [f'x{i}' for i in range(19, 30)]+['sp']+[f'd{i}' for i in range(8, 16)])),
          prop('scratch', refs('register', ['x16', 'x17'])), prop('platform-register', ref('register', 'x18')),
          prop('returns', refs('register', ['x0', 'x1', 'v0', 'v1', 'v2', 'v3'])),
          prop('rules', q('x30 link, x29 frame pointer, x8 indirect-result address. x16/x17 may be clobbered by veneers; x18 platform-reserved. v8-v15 only low64 callee-saved for base PCS. HFA/HVA of1..4 elements use SIMD regs; other aggregates <=16 bytes use GPR chunks with alignment; larger indirectly. SP remains16-aligned. Variadic save areas track separate GPR/SIMD classes; platform variants differ. SVE PCS requires distinct scalable saves and is not the base PCS.')))
    p.add('layout', 'branches', prop('instruction-bytes', 4), prop('branch-unit', 4), prop('unconditional-bits', 26), prop('conditional-bits', 19), prop('test-bit-bits', 14),
          prop('literal-bits', 19), prop('pc-base', 'instruction'), prop('relax', q('B/BL reach +/-128MiB; B.cond/CBZ/literal LDR +/-1MiB; TBZ +/-32KiB. Conditional long branch: invert around B. Out-of-range B/BL: ADRP+ADD+BR/BLR veneer with x16/x17; ADRP page reach +/-4GiB; absolute literal/relocation for larger models.')))
    for name, bits, formula in [('R_AARCH64_CALL26', 26, '(S+A-P)>>2'), ('R_AARCH64_JUMP26', 26, '(S+A-P)>>2'),
                                  ('R_AARCH64_CONDBR19', 19, '(S+A-P)>>2'), ('R_AARCH64_ADR_PREL_PG_HI21', 21, '(page(S+A)-page(P))>>12'),
                                  ('R_AARCH64_ADD_ABS_LO12_NC', 12, '(S+A)&4095'), ('R_AARCH64_ABS64', 64, 'S+A')]:
        p.add('relocation', name, prop('bits', bits), prop('formula', q(formula)), prop('rules', q('ELF64 RELA; instruction bitfields may be split. Check alignment/range unless relocation explicitly NC. ADRP and low12 consumers must refer to the same symbol/addend.')))
    for width in (32, 64):
        sf = 0x80000000 if width == 64 else 0
        cls = f'GR{width}'
        rr = [operand('rd', 5, cls=cls, access='write'), operand('rn', 5, cls=cls), operand('rm', 5, cls=cls)]
        fields = [('rd', 0, 5, 0), ('rn', 5, 5, 0), ('rm', 16, 5, 0)]
        for name, base, op, flags in [('add', 0x0b000000, 'add', False), ('sub', 0x4b000000, 'sub', False),
                                     ('adds', 0x2b000000, 'add', True), ('subs', 0x6b000000, 'sub', True),
                                     ('and', 0x0a000000, 'and', False), ('orr', 0x2a000000, 'or', False),
                                     ('eor', 0x4a000000, 'xor', False), ('ands', 0x6a000000, 'and', True),
                                     ('mul', 0x1b007c00, 'mul', False), ('udiv', 0x1ac00800, 'udiv', False),
                                     ('sdiv', 0x1ac00c00, 'sdiv', False), ('lslv', 0x1ac02000, 'shl', False),
                                     ('lsrv', 0x1ac02400, 'lshr', False), ('asrv', 0x1ac02800, 'ashr', False)]:
            right = bv('and', width, read('rm'), f'(const {width} {width-1})') if name.endswith('v') and name not in ('udiv', 'sdiv') else read('rm')
            value = bv(op, width, read('rn'), right)
            if name in ('udiv', 'sdiv'):
                # A64 differs from the shared/RISC-V divide-by-zero convention.
                value = f'(arm-div {op} {width} {read("rn")} {read("rm")})'
            code = write('rd', value)
            if flags:
                flag = f'(nzcv-{op} {width} {read("rn")} {read("rm")})' if op != 'and' else f'(nzcv-logic {width} {value})'
                code = parallel(code, flag)
            p.instruction(f'{name}{width}', base | sf, rr, fields, code, f'{name} {{rd}}, {{rn}}, {{rm}}',
                          effects='flags' if flags else 'pure', schedule='div' if 'div' in name else 'mul' if name == 'mul' else 'alu')
        for name, base, op in [('addi', 0x11000000, 'add'), ('subi', 0x51000000, 'sub')]:
            p.instruction(f'{name}{width}', base | sf,
                          [operand('rd', 5, cls=cls+'SP', access='write'), operand('rn', 5, cls=cls+'SP'), operand('imm', 12)],
                          [('rd', 0, 5, 0), ('rn', 5, 5, 0), ('imm', 10, 12, 0)], write('rd', bv(op, width, read('rn'), read('imm'))),
                          f'{name[:-1]} {{rd}}, {{rn}}, #{{imm}}')
        for name, base in [('movz', 0x52800000), ('movk', 0x72800000)]:
            shift = bv('mul', 64, read('hw'), '(const 64 16)')
            value = bv('shl', width, read('imm'), shift) if name == 'movz' else f'(deposit {read("rd")} {read("imm")} {shift} 16)'
            p.instruction(f'{name}{width}', base | sf,
                          [operand('rd', 5, cls=cls, access='write' if name == 'movz' else 'read-write'), operand('imm', 16), operand('hw', 2 if width == 64 else 1)],
                          [('rd', 0, 5, 0), ('imm', 5, 16, 0), ('hw', 21, 2 if width == 64 else 1, 0)], write('rd', value), f'{name} {{rd}}, #{{imm}}, lsl #{{hw*16}}')
        for name, base in [('ldr', 0xb9400000), ('str', 0xb9000000)]:
            address = bv('add', 64, read('base'), read('offset'))
            value = write('rt', f'(load {width} {address} little 1)') if name == 'ldr' else f'(store {width} {address} {read("rt")} little 1)'
            p.instruction(f'{name}{width}', base | (0x40000000 if width == 64 else 0),
                          [operand('rt', 5, cls=cls, access='write' if name == 'ldr' else 'read'), operand('base', 5, cls='GR64SP'), operand('offset', 12, scale=width//8)],
                          [('rt', 0, 5, 0), ('base', 5, 5, 0), ('offset', 10, 12, 0)], value,
                          f'{name} {{rt}}, [{{base}}, #{{offset}}]', effects='memory', schedule='load' if name == 'ldr' else 'store')
    p.add('pcode-op', 'arm-div', prop('arity', '4 4'), prop('effect', 'value'), prop('semantics', q('Arguments signed/unsigned opcode,width,a,b. Divide with truncation toward zero. Zero divisor returns zero. Signed MIN/-1 returns MIN. No integer divide exception.')))
    for name, base in [('b', 0x14000000), ('bl', 0x94000000)]:
        code = f'(jump {bv("add",64,"(pc)",read("disp"))})'
        if name == 'bl': code = parallel(code, '(set-reg x30 (next-pc))')
        p.instruction(name, base, [operand('disp', 26, True, 4)], [('disp', 0, 26, 0)], code, name+' {target}', effects='control', schedule='branch')
    for i, cond in enumerate(['eq', 'ne', 'cs', 'cc', 'mi', 'pl', 'vs', 'vc', 'hi', 'ls', 'ge', 'lt', 'gt', 'le']):
        p.instruction('b.'+cond, 0x54000000+i, [operand('disp', 19, True, 4)], [('disp', 5, 19, 0)],
                      f'(branch (arm-condition {i}) {bv("add",64,"(pc)",read("disp"))})', 'b.'+cond+' {target}', effects='control flags-read', schedule='branch')
    for name, base in [('br', 0xd61f0000), ('blr', 0xd63f0000), ('ret', 0xd65f0000)]:
        code = f'(jump {read("rn")})'
        if name == 'blr': code = parallel(code, '(set-reg x30 (next-pc))')
        p.instruction(name, base, [operand('rn', 5, cls='GR64')], [('rn', 5, 5, 0)], code, name+' {rn}', effects='control', schedule='branch', constraints='Register31 denotes XZR, not SP. Normal returns select X30; jumping to zero can fault at instruction fetch.')
    for width, load_base, store_base in [(8, 0x39400000, 0x39000000), (16, 0x79400000, 0x79000000)]:
        address = bv('add', 64, read('base'), read('offset'))
        for signed in (False, True):
            p.instruction(f'load{width}-'+('signed' if signed else 'unsigned'), (load_base ^ 0x00c00000) if signed else load_base,
                          [operand('rt', 5, cls='GR64' if signed else 'GR32', access='write'), operand('base', 5, cls='GR64SP'), operand('offset', 12, scale=width//8)],
                          [('rt', 0, 5, 0), ('base', 5, 5, 0), ('offset', 10, 12, 0)],
                          write('rt', f'({"sext" if signed else "zext"} {width} {64 if signed else 32} (load {width} {address} little 1))'),
                          ('ldrs' if signed else 'ldr')+('b' if width == 8 else 'h')+' {rt}, [{base}, #{offset}]', effects='memory', schedule='load')
        p.instruction(f'store{width}', store_base,
                      [operand('rt', 5, cls='GR32'), operand('base', 5, cls='GR64SP'), operand('offset', 12, scale=width//8)],
                      [('rt', 0, 5, 0), ('base', 5, 5, 0), ('offset', 10, 12, 0)],
                      f'(store {width} {address} {read("rt")} little 1)', ('strb' if width == 8 else 'strh')+' {rt}, [{base}, #{offset}]', effects='memory', schedule='store')
    for name, base in [('adr', 0x10000000), ('adrp', 0x90000000)]:
        pc = '(pc)' if name == 'adr' else bv('and', 64, '(pc)', '(const 64 0xfffffffffffff000)')
        p.instruction(name, base, [operand('rd', 5, cls='GR64', access='write'), operand('disp', 21, True, 4096 if name == 'adrp' else 1)],
                      [('rd', 0, 5, 0), ('disp', 29, 2, 0), ('disp', 5, 19, 2)], write('rd', bv('add', 64, pc, read('disp'))), name+' {rd}, {target}')
    for name, base, op in [('fadd', 0x1e602800, 'add'), ('fsub', 0x1e603800, 'sub'), ('fmul', 0x1e600800, 'mul'), ('fdiv', 0x1e601800, 'div')]:
        p.instruction(name+'64', base, [operand('rd', 5, cls='FPR64', access='write'), operand('rn', 5, cls='FPR64'), operand('rm', 5, cls='FPR64')],
                      [('rd', 0, 5, 0), ('rn', 5, 5, 0), ('rm', 16, 5, 0)], write('rd', f'(fp-bin {op} f64 {read("rn")} {read("rm")} fpcr)'), name+' {rd}, {rn}, {rm}', features=('fp',), effects='fp-environment', schedule='fp')
    for load in (True, False):
        address = bv('add', 64, read('base'), read('offset'))
        p.instruction('ldr-f64' if load else 'str-f64', 0xfd400000 if load else 0xfd000000,
                      [operand('rt', 5, cls='FPR64', access='write' if load else 'read'), operand('base', 5, cls='GR64SP'), operand('offset', 12, scale=8)],
                      [('rt', 0, 5, 0), ('base', 5, 5, 0), ('offset', 10, 12, 0)],
                      write('rt', f'(load 64 {address} little 1)') if load else f'(store 64 {address} {read("rt")} little 1)',
                      ('ldr' if load else 'str')+' {rt}, [{base}, #{offset}]', features=('fp',), effects='memory', schedule='load' if load else 'store')
    for name, base, dest, src in [('fmov64', 0x1e604000, 'FPR64', 'FPR64'), ('fmov-to-gpr', 0x9e660000, 'GR64', 'FPR64'), ('fmov-from-gpr', 0x9e670000, 'FPR64', 'GR64')]:
        p.instruction(name, base, [operand('rd', 5, cls=dest, access='write'), operand('rn', 5, cls=src)],
                      [('rd', 0, 5, 0), ('rn', 5, 5, 0)], write('rd', read('rn')), 'fmov {rd}, {rn}', features=('fp',))
    p.instruction('add-v4i32', 0x4ea08400, [operand('rd', 5, cls='V128', access='write'), operand('rn', 5, cls='V128'), operand('rm', 5, cls='V128')],
                  [('rd', 0, 5, 0), ('rn', 5, 5, 0), ('rm', 16, 5, 0)], write('rd', f'(vector-bin add i32 4 {read("rn")} {read("rm")})'),
                  'add {rd}.4s, {rn}.4s, {rm}.4s', features=('simd',), schedule='alu')
    for name, base, code in [('nop', 0xd503201f, '(nop)'), ('dmb-ish', 0xd5033bbf, '(fence inner-shareable inner-shareable)'), ('brk0', 0xd4200000, '(trap brk)')]:
        p.instruction(name, base, [], [], code, name.replace('-', ' '), effects='barrier', schedule='serial')
    for extension in ['lse', 'sve', 'sve2', 'pauth', 'bti', 'crypto', 'mte']:
        p.add('extension', extension, prop('requires', ref('feature', extension)), prop('coverage', 'metadata-only'),
              prop('semantics', q('Extension-specific state, predicates, fault and ordering behavior must be modeled before adding forms. Base scalar/NEON lowering or runtime helpers are the current fallback; SVE scalable operations without a backend are diagnosed.')))
    for ir, form in [('add', 'add64'), ('sub', 'sub64'), ('mul', 'mul64'), ('sdiv', 'sdiv64'), ('udiv', 'udiv64'), ('and', 'and64'), ('load', 'ldr64'), ('store', 'str64')]:
        p.add('selection', ir, prop('pattern', f'(ir-op {ir} i64)'), prop('type', ref('type', 'i64')), prop('instruction', ref('instruction', form)), prop('cost', 1),
              prop('constraints', q('Three-address operands; SP/ZR interpretation follows each operand class. Language division traps/UB must be handled before using nontrapping machine division.')))
    return p


def risv():
    p = Profile('risv')
    common(p, ['base', 'm', 'a', 'f', 'd'], 'lp64d', 'riscv64-unknown-linux-gnu', 'RISC-V unprivileged ISA RV64I/M/A/F/D/C, vector specification1.0 and RISC-V ELF psABI. Filename risv.aml follows the requested spelling.')
    for name, desc, deps in [('base', 'RV64I, XLEN64, little-endian', []), ('m', 'Integer multiply/divide', ['base']),
                              ('a', 'LR/SC and AMO', ['base']), ('f', 'Single precision, FLEN>=32', ['base']),
                              ('d', 'Double precision, FLEN>=64', ['f']), ('c', 'Compressed16-bit forms; IALIGN16', ['base']),
                              ('zicsr', 'CSR access', ['base']), ('zifencei', 'Instruction fetch synchronization', ['base']),
                              ('v', 'Vector1.0, scalable VLEN, SEW/LMUL/VL state', ['base']), ('zba', 'Address generation', ['base']),
                              ('zbb', 'Basic bit manipulation', ['base']), ('zbs', 'Single-bit operations', ['base']),
                              ('ztso', 'Stronger total store order', ['base'])]:
        p.feature(name, desc, deps)
    aliases = ['zero', 'ra', 'sp', 'gp', 'tp', 't0', 't1', 't2', 's0', 's1'] + [f'a{i}' for i in range(8)] + [f's{i}' for i in range(2, 12)] + ['t3', 't4', 't5', 't6']
    for i in range(32):
        p.storage(f'x{i}', 64); p.reg(f'x{i}', 64, f'x{i}', i, i, write='discard' if i == 0 else 'replace')
        p.reg(aliases[i], 64, f'x{i}', i, i, write='discard' if i == 0 else 'replace')
        p.storage(f'f{i}', 64); p.reg(f'f{i}', 64, f'f{i}', i, 32+i)
        p.storage(f'v{i}', 65536, True); p.reg(f'v{i}', 65536, f'v{i}', i)
    p.reg('fp', 64, 'x8', 8, 8)
    for name in ['pc', 'fcsr', 'vl', 'vtype', 'vstart', 'vxrm', 'vxsat']:
        width = 32 if name == 'fcsr' else 64
        p.storage(name, width); p.reg(name, width, name, 0)
    p.regclass('GPR', [f'x{i}' for i in range(32)], 64, ['x0', 'x2', 'x3', 'x4'])
    p.regclass('FPR', [f'f{i}' for i in range(32)], 64)
    p.regclass('VR', [f'v{i}' for i in range(32)], 65536, scalable='true', groups='1 2 4 8', group_alignment='LMUL')
    for name, privilege in [('user', 0), ('supervisor', 1), ('machine', 3)]:
        p.add('mode', name, prop('xlen', 64), prop('privilege', privilege), prop('ialign', '32-or-16-with-c'),
              prop('rules', q('This compiler profile emits user-mode integer/FP code. Supervisor/machine CSR state is metadata; privilege transitions and page tables require a separate execution environment.')))
    p.add('memory', 'normal', prop('model', 'RVWMO'), prop('endian', 'little'), prop('address-bits', 64),
          prop('rules', q('Execution environment defines misaligned access support; compiler assumes natural alignment and expands unaligned accesses. Loads/stores are not implicit fences. Sv39/Sv48/Sv57 virtual addressing and physical addressing are platform configuration. Atomicity guaranteed only at supported widths/alignment/access type.')))
    p.add('addressing', 'base-signed12', prop('displacement-bits', 12), prop('scale', 1),
          prop('rules', q('Address=XLEN base+sign-extended immediate, no scaled index. AUIPC/LUI plus ADDI/load/store pairs materialize larger addresses. Rounded high20=(offset+0x800)>>12; low12 is signed.')))
    p.add('atomic', 'rvwmo', prop('order-bits', 'aq=2 rl=1'), prop('rules', q('AMO aq/rl affect the accessed address domain. LR/SC reservations may fail spuriously; constrained retry loops have forward-progress rules. FENCE orders predecessor/successor I/O or memory classes; seq-cst mappings require the language-specific fence/aqrl sequence. Natural alignment mandatory. No A extension: runtime lock helpers.')))
    p.add('exception', 'precise', prop('kinds', 'instruction-misaligned instruction-access illegal-instruction breakpoint load/store-misaligned load/store-access ecall page-fault'),
          prop('rules', q('xepc/xcause/xtval and trap vector are privilege/environment state. Integer division is nontrapping: divide by zero quotient all ones and remainder dividend; signed MIN/-1 quotient MIN, remainder0. FP exceptions accumulate fflags; no standard synchronous FP arithmetic trap.')))
    p.add('vector', 'rvv1', prop('vlen-min-bits', 128), prop('vlen-max-bits', 65536), prop('state', refs('register', ['vl', 'vtype', 'vstart', 'vxrm', 'vxsat'])),
          prop('rules', q('VLMAX=LMUL*VLEN/SEW; LMUL in fractional1/8..8, register groups aligned to integer LMUL. v0 is mask, inactive/tail policy follows vma/vta; agnostic values are not assumed zero. Strip-mine using returned VL. Widening/narrowing alter EMUL and overlap restrictions. FP scalar narrower values are NaN-boxed with all upper FLEN bits one; malformed boxes read as canonical NaN. Arithmetic NaN results are canonical quiet NaNs (f32=0x7fc00000,f64=0x7ff8000000000000); signaling NaNs set invalid. fcsr frm selects rounding and fflags are sticky. rm0 RNE,1 RTZ,2 RDN,3 RUP,4 RMM,7 dynamic;5/6 reserved. Subnormals supported with tininess detected after rounding.')))
    p.add('predication', 'branches-and-v0', prop('scalar', 'no-condition-flags'), prop('vector-mask', ref('register', 'v0')),
          prop('rules', q('Scalar comparisons feed branches or 0/1 GPR values; signed and unsigned branches are distinct. RVV mask is a packed predicate with bit index equal to element index.')))
    p.add('syntax', 'gas', prop('operand-order', 'destination-first'), prop('rules', q('ABI or xN/fN register names; immediate plain; offset(base) memory. .option arch and .option rvc/norvc control extensions. Pseudo li/la/call/ret expand into actual forms and relocations; encoder accepts only concrete records.')))
    p.add('abi', 'lp64d', prop('stack-align', 16), prop('red-zone', 0), prop('stack-pointer', ref('register', 'sp')),
          prop('integer-args', refs('register', [f'a{i}' for i in range(8)])), prop('float-args', refs('register', [f'f{i}' for i in range(10, 18)])),
          prop('callee-saved', refs('register', ['sp', 's0', 's1']+[f's{i}' for i in range(2, 12)]+[f'f{i}' for i in [8, 9]+list(range(18, 28))])),
          prop('returns', refs('register', ['a0', 'a1', 'f10', 'f11'])),
          prop('rules', q('gp/tp unallocatable; ra caller-saved, s0 optional frame pointer. Integer values narrower than XLEN are extended to32 according to signedness then sign-extended toXLEN, including unsigned32. Aggregates <=2*XLEN pass in one/two GPRs; larger indirectly. Hard-float named args use fa0-fa7 for eligible flattened one/two-field aggregates; varargs use integer convention with aligned register pairs for2*XLEN alignment. FP callee saves apply only up to ABI_FLEN64. Standard vector convention passes vectors indirectly; vector calling-convention variant requires separate ABI data.')))
    p.add('abi', 'lp64', prop('stack-align', 16), prop('integer-args', refs('register', [f'a{i}' for i in range(8)])),
          prop('rules', q('Soft-float calling convention: FP values passed in integer registers/stack; same integer preservation and aggregate rules as LP64D. Select this ABI for targets/runtimes without D; do not link incompatible ELF float-ABI flags.')))
    p.add('layout', 'branches', prop('instruction-bytes', '2 4'), prop('branch-unit', 2), prop('conditional-bits', 12), prop('jal-bits', 20),
          prop('pc-base', 'instruction'), prop('relax', q('B-type signed13 byte displacement, JAL signed21. Conditional long branch: inverted branch over JAL or AUIPC+JALR. CALL pair uses rounded high20 and signed low12; JALR clears target bit0. RVC reduces IALIGN to16. Literal pools need AUIPC reach or address materialization. Preserve relocation pairs during linker relaxation.')))
    for name, bits, formula in [('R_RISCV_BRANCH', 12, '(S+A-P)>>1'), ('R_RISCV_JAL', 20, '(S+A-P)>>1'),
                                  ('R_RISCV_PCREL_HI20', 20, '(S+A-P+0x800)>>12'), ('R_RISCV_PCREL_LO12_I', 12, 'low12-of-paired-HI20'),
                                  ('R_RISCV_PCREL_LO12_S', 12, 'low12-of-paired-HI20'), ('R_RISCV_64', 64, 'S+A')]:
        p.add('relocation', name, prop('bits', bits), prop('formula', q(formula)), prop('rules', q('ELF64 RELA. Low12 relocations reference the label of the paired AUIPC, not directly the target symbol. R_RISCV_RELAX is an explicit linker relaxation annotation; preserve pair identity.')))
    rr = [operand('rd', 5, cls='GPR', access='write'), operand('rs1', 5, cls='GPR'), operand('rs2', 5, cls='GPR')]
    fields = [('rd', 7, 5, 0), ('rs1', 15, 5, 0), ('rs2', 20, 5, 0)]
    for name, funct3, funct7, op in [('add', 0, 0, 'add'), ('sub', 0, 32, 'sub'), ('sll', 1, 0, 'shl'),
                                      ('slt', 2, 0, None), ('sltu', 3, 0, None), ('xor', 4, 0, 'xor'),
                                      ('srl', 5, 0, 'lshr'), ('sra', 5, 32, 'ashr'), ('or', 6, 0, 'or'), ('and', 7, 0, 'and'),
                                      ('mul', 0, 1, 'mul'), ('div', 4, 1, 'sdiv'), ('divu', 5, 1, 'udiv'), ('rem', 6, 1, 'srem'), ('remu', 7, 1, 'urem')]:
        right = bv('and', 64, read('rs2'), '(const 64 63)') if name in ('sll', 'srl', 'sra') else read('rs2')
        value = bv(op, 64, read('rs1'), right) if op else f'(bool-int 64 ({"slt" if name == "slt" else "ult"} {read("rs1")} {read("rs2")}))'
        p.instruction(name, 0x33 | funct3 << 12 | funct7 << 25, rr, fields, write('rd', value), name+' {rd}, {rs1}, {rs2}',
                      features=('m',) if funct7 == 1 else ('base',), schedule='div' if name.startswith(('div', 'rem')) else 'mul' if name == 'mul' else 'alu')
        if name in ('add', 'sub', 'sll', 'srl', 'sra', 'mul', 'div', 'divu', 'rem', 'remu'):
            right = bv('and', 32, read('rs2'), '(const 32 31)') if name in ('sll', 'srl', 'sra') else read('rs2')
            p.instruction(name+'w', 0x3b | funct3 << 12 | funct7 << 25, rr, fields,
                          write('rd', f'(sext 32 64 {bv(op,32,read("rs1"),right)})'), name+'w {rd}, {rs1}, {rs2}',
                          features=('m',) if funct7 == 1 else ('base',), schedule='div' if name.startswith(('div', 'rem')) else 'alu')
    for name, f3, op in [('addi', 0, 'add'), ('slti', 2, None), ('sltiu', 3, None), ('xori', 4, 'xor'), ('ori', 6, 'or'), ('andi', 7, 'and')]:
        value = bv(op, 64, read('rs1'), read('imm')) if op else f'(bool-int 64 ({"slt" if name == "slti" else "ult"} {read("rs1")} {read("imm")}))'
        p.instruction(name, 0x13 | f3 << 12, [rr[0], rr[1], operand('imm', 12, True)],
                      [('rd', 7, 5, 0), ('rs1', 15, 5, 0), ('imm', 20, 12, 0)], write('rd', value), name+' {rd}, {rs1}, {imm}')
    for name, base, op in [('slli', 0x1013, 'shl'), ('srli', 0x5013, 'lshr'), ('srai', 0x40005013, 'ashr')]:
        p.instruction(name, base, [rr[0], rr[1], operand('shamt', 6)], [('rd', 7, 5, 0), ('rs1', 15, 5, 0), ('shamt', 20, 6, 0)],
                      write('rd', bv(op, 64, read('rs1'), read('shamt'))), name+' {rd}, {rs1}, {shamt}')
    for name, f3, width, sign in [('lb', 0, 8, True), ('lh', 1, 16, True), ('lw', 2, 32, True), ('ld', 3, 64, False),
                                  ('lbu', 4, 8, False), ('lhu', 5, 16, False), ('lwu', 6, 32, False)]:
        address = bv('add', 64, read('rs1'), read('imm'))
        value = f'(load {width} {address} little {width//8})'
        if width != 64: value = f'({"sext" if sign else "zext"} {width} 64 {value})'
        p.instruction(name, 0x03 | f3 << 12, [rr[0], rr[1], operand('imm', 12, True)],
                      [('rd', 7, 5, 0), ('rs1', 15, 5, 0), ('imm', 20, 12, 0)], write('rd', value), name+' {rd}, {imm}({rs1})', effects='memory', schedule='load')
    for name, f3, width in [('sb', 0, 8), ('sh', 1, 16), ('sw', 2, 32), ('sd', 3, 64)]:
        p.instruction(name, 0x23 | f3 << 12, [rr[1], rr[2], operand('imm', 12, True)],
                      [('rs1', 15, 5, 0), ('rs2', 20, 5, 0), ('imm', 7, 5, 0), ('imm', 25, 7, 5)],
                      f'(store {width} {bv("add",64,read("rs1"),read("imm"))} {read("rs2")} little {width//8})',
                      name+' {rs2}, {imm}({rs1})', effects='memory', schedule='store')
    for name, f3, cmp in [('beq', 0, 'eq'), ('bne', 1, 'ne'), ('blt', 4, 'slt'), ('bge', 5, 'sge'), ('bltu', 6, 'ult'), ('bgeu', 7, 'uge')]:
        p.instruction(name, 0x63 | f3 << 12, [rr[1], rr[2], operand('disp', 12, True, 2)],
                      [('rs1', 15, 5, 0), ('rs2', 20, 5, 0), ('disp', 8, 4, 0), ('disp', 25, 6, 4), ('disp', 7, 1, 10), ('disp', 31, 1, 11)],
                      f'(branch ({cmp} {read("rs1")} {read("rs2")}) {bv("add",64,"(pc)",read("disp"))})', name+' {rs1}, {rs2}, {target}', effects='control', schedule='branch')
    p.instruction('jal', 0x6f, [rr[0], operand('disp', 20, True, 2)],
                  [('rd', 7, 5, 0), ('disp', 21, 10, 0), ('disp', 20, 1, 10), ('disp', 12, 8, 11), ('disp', 31, 1, 19)],
                  parallel(write('rd', '(next-pc)'), f'(jump {bv("add",64,"(pc)",read("disp"))})'), 'jal {rd}, {target}', effects='control', schedule='branch')
    p.instruction('jalr', 0x67, [rr[0], rr[1], operand('imm', 12, True)], [('rd', 7, 5, 0), ('rs1', 15, 5, 0), ('imm', 20, 12, 0)],
                  parallel(write('rd', '(next-pc)'), f'(jump {bv("and",64,bv("add",64,read("rs1"),read("imm")),"(const 64 0xfffffffffffffffe)")})'),
                  'jalr {rd}, {imm}({rs1})', effects='control', schedule='branch')
    for name, base in [('lui', 0x37), ('auipc', 0x17)]:
        value = read('imm') if name == 'lui' else bv('add', 64, '(pc)', read('imm'))
        p.instruction(name, base, [rr[0], operand('imm', 20, True, 4096)], [('rd', 7, 5, 0), ('imm', 12, 20, 0)], write('rd', value), name+' {rd}, {imm>>12}')
    for width in (32, 64):
        f3 = 2 if width == 32 else 3
        for name, f5, op in [('amoadd', 0, 'add'), ('amoswap', 1, 'swap'), ('amoxor', 4, 'xor'), ('amoor', 8, 'or'),
                               ('amoand', 12, 'and'), ('amomin', 16, 'smin'), ('amomax', 20, 'smax'), ('amominu', 24, 'umin'), ('amomaxu', 28, 'umax')]:
            p.instruction(name+('.w' if width == 32 else '.d'), 0x2f | f3 << 12 | f5 << 27, rr+[operand('order', 2)],
                          fields+[('order', 25, 2, 0)], write('rd', f'(amo {op} {width} {read("rs1")} {read("rs2")} {read("order")})'),
                          name+('.w' if width == 32 else '.d')+'{aqrl} {rd}, {rs2}, ({rs1})', features=('a',), effects='atomic memory', schedule='serial')
        p.instruction('lr'+str(width), 0x1000002f | f3 << 12, rr[:2]+[operand('order', 2)],
                      fields[:2]+[('order', 25, 2, 0)], write('rd', f'(reserve-load {width} {read("rs1")} {read("order")})'),
                      'lr'+('.w' if width == 32 else '.d')+'{aqrl} {rd}, ({rs1})', features=('a',), effects='atomic memory', schedule='serial')
        p.instruction('sc'+str(width), 0x1800002f | f3 << 12, rr+[operand('order', 2)], fields+[('order', 25, 2, 0)],
                      write('rd', f'(conditional-store {width} {read("rs1")} {read("rs2")} {read("order")})'),
                      'sc'+('.w' if width == 32 else '.d')+'{aqrl} {rd}, {rs2}, ({rs1})', features=('a',), effects='atomic memory', schedule='serial')
    for name, f7, op in [('fadd.d', 1, 'add'), ('fsub.d', 5, 'sub'), ('fmul.d', 9, 'mul'), ('fdiv.d', 13, 'div')]:
        p.instruction(name, 0x53 | f7 << 25,
                      [operand('rd', 5, cls='FPR', access='write'), operand('rs1', 5, cls='FPR'), operand('rs2', 5, cls='FPR'), operand('rm', 3, exclude=(5, 6))],
                      fields+[('rm', 12, 3, 0)], write('rd', f'(fp-bin {op} f64 {read("rs1")} {read("rs2")} {read("rm")})'),
                      name+' {rd}, {rs1}, {rs2}, {rm}', features=('d',), effects='fp-environment', schedule='fp', constraints='rm 0..4 static rounding,7 dynamic frm;5/6 reserved and must not be selected.')
    address = bv('add', 64, read('rs1'), read('imm'))
    p.instruction('fld', 0x3007, [operand('rd', 5, cls='FPR', access='write'), rr[1], operand('imm', 12, True)],
                  [('rd', 7, 5, 0), ('rs1', 15, 5, 0), ('imm', 20, 12, 0)], write('rd', f'(load 64 {address} little 8)'),
                  'fld {rd}, {imm}({rs1})', features=('d',), effects='memory', schedule='load')
    p.instruction('fsd', 0x3027, [rr[1], operand('rs2', 5, cls='FPR'), operand('imm', 12, True)],
                  [('rs1', 15, 5, 0), ('rs2', 20, 5, 0), ('imm', 7, 5, 0), ('imm', 25, 7, 5)],
                  f'(store 64 {address} {read("rs2")} little 8)', 'fsd {rs2}, {imm}({rs1})', features=('d',), effects='memory', schedule='store')
    p.instruction('fsgnj.d', 0x22000053, [operand('rd', 5, cls='FPR', access='write'), operand('rs1', 5, cls='FPR'), operand('rs2', 5, cls='FPR')], fields,
                  write('rd', f'(deposit {read("rs1")} (extract {read("rs2")} 63 1) 63 1)'), 'fsgnj.d {rd}, {rs1}, {rs2}', features=('d',))
    for name, base, dest, src in [('fmv.x.d', 0xe2000053, 'GPR', 'FPR'), ('fmv.d.x', 0xf2000053, 'FPR', 'GPR')]:
        p.instruction(name, base, [operand('rd', 5, cls=dest, access='write'), operand('rs1', 5, cls=src)],
                      [('rd', 7, 5, 0), ('rs1', 15, 5, 0)], write('rd', read('rs1')), name+' {rd}, {rs1}', features=('d',))
    for name, base, code in [('ecall', 0x73, '(trap ecall)'), ('ebreak', 0x100073, '(trap breakpoint)'), ('fence-rw-rw', 0x0330000f, '(fence rw rw)')]:
        p.instruction(name, base, [], [], code, name.replace('-', ' '), effects='barrier', schedule='serial')
    p.instruction('fence.i', 0x100f, [], [], '(fence instruction-fetch instruction-fetch)', 'fence.i', features=('zifencei',), effects='barrier', schedule='serial')
    p.instruction('c.nop', '0100', [], [], '(nop)', 'c.nop', features=('c',))
    p.instruction('c.ebreak', '0290', [], [], '(trap breakpoint)', 'c.ebreak', features=('c',), effects='control', schedule='serial')
    for extension in ['v', 'zba', 'zbb', 'zbs', 'ztso', 'zicsr']:
        p.add('extension', extension, prop('requires', ref('feature', extension)), prop('coverage', 'metadata-only'),
              prop('semantics', q('Use exact extension forms only after implementing their state, ordering, legalization and encoding. Base scalar lowering remains available; V scalable types require an enabled vector backend. Ztso strengthens memory order without changing ordinary integer encodings.')))
    for ir, form in [('add', 'add'), ('sub', 'sub'), ('mul', 'mul'), ('sdiv', 'div'), ('udiv', 'divu'), ('and', 'and'), ('load', 'ld'), ('store', 'sd')]:
        p.add('selection', ir, prop('pattern', f'(ir-op {ir} i64)'), prop('type', ref('type', 'i64')), prop('instruction', ref('instruction', form)), prop('cost', 1),
              prop('constraints', q('Three-address GPR operands; no condition flags. x0 writes discarded. M/A/FP feature checks and runtime fallback must precede selection.')))
    return p


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    for build in [amd64, arm64, risv]:
        profile = build()
        path = ROOT / 'library' / 'archml' / (profile.name + '.aml')
        text = profile.render()
        if args.check:
            if not path.is_file() or path.read_text() != text:
                parser.exit(1, f'stale ArchML profile: {path}\n')
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text)
        print(f'{profile.name}: {len(profile.instructions)} concrete instructions, {len(profile.records)} records')


if __name__ == '__main__':
    main()
